head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.gNowDutyYn = '';
scwin.gNowDutyStat = '';
scwin.gDepCd;
scwin.gEmpNo;
scwin.gLdMktTp = js_market;
scwin.gAcptNo;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        $c.cm.PanelToGroupBox(panel_3); // 검색조건 패널에 스타일 적용

        txb_EMP_NM.setValue(js_emp_nm);
        await scwin.setCode();

        // 가우스헤더 셋팅
        const sbmOptions = {
            id : "sbm_dts_CloseProcs",
            action : "/gauceSystemierAdaptor.do",
            ref : "",
            target : "dts_CloseProcs=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

        await scwin.oneSearch();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF31010.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_Search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Search_onclick = async function() {
    try {
        await scwin.historySearch(); // 조회 버튼
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF31010.btn_Search_onclick" });
    }
};

/**
 * @method
 * @name dts_Grid_OnLoadError
 * @description dts_Grid 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_Grid_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_Grid);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF31010.dts_Grid_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_OneGrid_OnLoadError
 * @description dts_OneGrid 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_OneGrid_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_OneGrid);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF31010.dts_OneGrid_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_DutyStatus_OnLoadError
 * @description dts_DutyStatus 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_DutyStatus_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_DutyStatus);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF31010.dts_DutyStatus_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_Grid_OnLoadCompleted
 * @description dts_Grid 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_Grid_OnLoadCompleted = function(rowcount) {
    try {
        $c.stf.fillGridHeaderTotalCnt(rowcount, panel_page); // 총 건수
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF31010.dts_Grid_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name dts_OneGrid_OnLoadCompleted
 * @description dts_OneGrid 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_OneGrid_OnLoadCompleted = function(rowcount) {

};

/**
 * @method
 * @name dts_DutyStatus_OnLoadCompleted
 * @description dts_DutyStatus 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_DutyStatus_OnLoadCompleted = function(rowcount) {
    try {
        scwin.gNowDutyYn = dts_DutyStatus.getCellData(1, 'NOW_DUTY_YN');
        scwin.gNowDutyStat = dts_DutyStatus.getCellData(1, 'NOW_DUTY_STAT');
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF31010.dts_DutyStatus_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name trs_CloseProcs_OnSuccess
 * @description Close Procs On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_CloseProcs_OnSuccess = async function() {
    try {
        await $c.win.alert($c.stf.getMessageParam("MSG-0001", ""));
        await scwin.oneSearch();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF31010.trs_CloseProcs_OnSuccess" });
    }
};

/**
 * @method
 * @name trs_CloseProcs_OnFail
 * @description Close Procs On Fail 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_CloseProcs_OnFail = async function() {
    try {
        await $c.win.alert('trs_CloseProcs.OnFail() :' + trs_CloseProcs.ErrorMsg);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF31010.trs_CloseProcs_OnFail" });
    }
};

/**
 * @method
 * @name cmb_PeriodTp_onselchange
 * @description cmb_PeriodTp onselchange 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.cmb_PeriodTp_onselchange = function() {
    try {
        const vTp = cmb_PeriodTp.getValue();
        $c.stf.setFromToDate(vTp, edt_SDATE, edt_EDATE); // 기간선택 콤보박스
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF31010.cmb_PeriodTp_onselchange" });
    }
};

/**
 * @method
 * @name btn_EDATE_onclick
 * @description btn_EDATE 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_EDATE_onclick = function() {
    try {
        popUpCalendar2(edt_EDATE); // 공시일자-시작일 이미지 버튼 클릭 시 달력 팝업
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF31010.btn_EDATE_onclick" });
    }
};

/**
 * @method
 * @name btn_SDATE_onclick
 * @description btn_SDATE 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_SDATE_onclick = function() {
    try {
        popUpCalendar2(edt_SDATE); // 공시일자-종료일 이미지 버튼 클릭 시 달력 팝업
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF31010.btn_SDATE_onclick" });
    }
};

/**
 * @method
 * @name btn_Excel_onclick
 * @description 「엑셀다운로드」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Excel_onclick = function() {
    try {
        $c.data.downloadGridViewExcel(grd_Grid, {fileName: "공시당번이력조회", type: "8"});
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF31010.btn_Excel_onclick" });
    }
};

/**
 * @method
 * @name btn_duty_start_onclick
 * @description 「당번업무시작」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_duty_start_onclick = async function() {
    try {
        await scwin.closeProcess('S');
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF31010.btn_duty_start_onclick" });
    }
};

/**
 * @method
 * @name btn_duty_close_onclick
 * @description 「당번업무마감」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_duty_close_onclick = async function() {
    try {
        await scwin.closeProcess('E');
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF31010.btn_duty_close_onclick" });
    }
};

/**
 * @method
 * @name MxTab_1_OnSelChanged
 * @description Mx Tab 1 On Sel Changed 처리
 * @param {*} nIndex nIndex
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.MxTab_1_OnSelChanged = async function(nIndex) {
    try {
        if (MxTab_1.getSelectedTabIndex() === 1) {
            await scwin.oneSearch();
        } else if (MxTab_1.getSelectedTabIndex() === 2) {
            await scwin.historySearch();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF31010.MxTab_1_OnSelChanged" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name setCode
 * @description set Code 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setCode = async function() {
    scwin.gDepCd = js_dep_cd;
    scwin.gEmpNo = js_emp_no;
    scwin.gLdMktTp = js_market;
    rdo_MKT_ID.setValue(scwin.gLdMktTp);
    if (scwin.gLdMktTp !== '9') {
        panel_mkt.hide();
    }

    //  기간 from~ to  셋팅
    let vCurDate = $c.ut.cGetToday("yyyymmdd");
    edt_SDATE.setValue(vCurDate); // 현재날짜
    edt_EDATE.setValue(vCurDate); // 현재날짜

    const sbmOptions = {
        id : "sbm_dts_CodeChrgEmpNo",
        action : "/CodeAction.do",
        ref : "",
        target : "dts_CodeChrgEmpNo=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    const sbmOptions2 = {
        id : "sbm_dts_CodeEmpNo",
        action : "/CodeAction.do",
        ref : "",
        target : "dts_CodeEmpNo=body.content",
        isProcessMsg : false
    };

    const sbmRtn2 = await $c.sbm.executeDynamic(sbmOptions2);
    // TODO Stage2: sbmRtn2 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    dts_CodeChrgEmpNo.setBroadcast(false);
    for (let i = 1; i <= dts_CodeEmpNo.getRowCount(); i++) {
        if ("" !== dts_CodeEmpNo.getCellData(i, 1)) {
            dts_CodeChrgEmpNo.insertRow();
            const crow = dts_CodeChrgEmpNo.getRowCount();
            dts_CodeChrgEmpNo.setCellData(crow, "VALUE", dts_CodeEmpNo.getCellData(i, 1));
            dts_CodeChrgEmpNo.setCellData(crow, "TEXT", dts_CodeEmpNo.getCellData(i, 2));
        }
    }
    dts_CodeChrgEmpNo.setBroadcast(true, true);
    dts_CodeChrgEmpNo.setRowPosition(1, 0);
    scwin.setTime();
};

/**
 * @method
 * @name historySearch
 * @description 조회 버튼
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.historySearch = async function() {
    url += "&MKT_ID=" + rdo_MKT_ID.getValue(); // 시장구분
    url += "&ChrgEmpNo=" + cmb_ChrgEmpNo.getValue();
    url += "&EmpNo=" + cmb_EmpNo.getValue();
    url += "&SDate=" + edt_SDATE.getValue();
    url += "&EDate=" + edt_EDATE.getValue();
    if (js_dep_cd === "2430") {
        url += "&GDUTY=";
    } else {
        url += "&GDUTY=" + js_gduty;
    }
    url += "&SCREN_ID=" + 'ULDSTF31010.xml';
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    const sbmOptions = {
        id : "sbm_dts_Grid",
        action : "/PersonOnDuty.do",
        ref : "",
        target : "dts_Grid=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name oneSearch
 * @description one Search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.oneSearch = async function() {
    setTimeout("fn_OneSearch()", 60000); // 1초 = 1000 , 60초 = 60000

    url += "&MKT_ID=" + rdo_MKT_ID.getValue(); // 시장구분
    if (js_dep_cd === "2430") {
        url += "&GDUTY=";
    } else {
        url += "&GDUTY=" + js_gduty;
    }
    url += "&EmpNo=" + js_emp_no;
    const sbmOptions = {
        id : "sbm_dts_OneGrid",
        action : "/PersonOnDuty.do",
        ref : "",
        target : "dts_OneGrid=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name closeProcess
 * @description 당번업무 시작 및 마감 처리 - 1 : 당번업무 시작 - 2 : 당번업무 마감
 * @param {*} pCloseStep pCloseStep
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.closeProcess = async function(pCloseStep) {
    scwin.checkStatus();
    if (scwin.gNowDutyYn !== 'Y') {
        await $c.win.alert("금일당번만 선택할 수 있습니다.");
        return;
    }
    if (scwin.gNowDutyStat === 'S' && pCloseStep === 'S') {
        await $c.win.alert("현재 당번업무 시작 상태입니다.");
        return;
    }
    if (scwin.gNowDutyStat === 'E' && pCloseStep === 'E') {
        await $c.win.alert("현재 당번업무 마감 상태입니다.");
        return;
    }
    if (scwin.gNowDutyStat === 'N' && pCloseStep === 'E') {
        await $c.win.alert("먼저 당번업무 시작부터 하시기 바랍니다.");
        return;
    }
    dts_CloseProcs.removeAll();
    dts_CloseProcs.insertRow();
    dts_CloseProcs.setCellData(1, "SEQ", scwin.gEmpNo);
    dts_CloseProcs.setCellData(1, "INTEG_USR_ID", scwin.gEmpNo);
    dts_CloseProcs.setCellData(1, "BZ_STRT_CLS_TP_CD", pCloseStep);
    let vProcMsg = "";
    if (pCloseStep === 'S') {
        vProcMsg = "당번업무 시작";
    } else if (pCloseStep === 'E') {
        vProcMsg = "당번업무 마감";
    }
    const vAnswer = confirm($c.stf.getMessageParam("MSG-A006", vProcMsg));
    if (vAnswer === true) {
        trs_CloseProcs.KeyName = "toinb_dataid4";
        const sbmOptions = {
            id : "sbm_trs_CloseProcs",
            action : "/PersonOnDuty.do",
            ref : "dts_CloseProcs",
            target : "trs_CloseProcs=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
    }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name setTime
 * @description 조회 버튼
 * @returns {void}
 * @hidden N
 */
scwin.setTime = function() {
    /*
    serverTime =	frame.Provider("/top").serverYear+ "년" +
    						frame.Provider("/top").serverMonth+ "월" +
    						frame.Provider("/top").serverDay+ "일" +
    						frame.Provider("/top").serverHours +
    						frame.Provider("/top").displayTime(frame.Provider("/top").serverMinutes) +
    						frame.Provider("/top").displayTime(frame.Provider("/top").serverSeconds);
    setObjectValue(txa_step_3,  serverTime);
     */
    let vCurDate = $c.ut.cGetToday("yyyy-mm-dd hh:mm:ss");
    txb_now.setValue("현재시각 : " + vCurDate);
    scwin.runClock();
};

/**
 * @method
 * @name runClock
 * @description run Clock 처리
 * @returns {void}
 * @hidden N
 */
scwin.runClock = function() {
    setTimeout("fn_setTime()", 1000);
};

/**
 * @method
 * @name checkStatus
 * @description check Status 처리
 * @returns {void}
 * @hidden N
 */
scwin.checkStatus = function() {
    $c.stf.checkDutyTimeStatus(js_emp_no, '', dts_DutyStatus); // fn_checkDutyTimeStatus(pEmpNo, pAcptNo, pDtsObj)

};
